"""Humanizer: personas, human timing and message generation.

Design goals: nothing the agent posts looks like a bot template.

* persona files define tone, language mix, length, emoji rate, slang, typo rate
* messages are generated by an LLM (provider cascade) with the channel's recent
  memory; if no provider is configured a template engine still produces varied text
* timing mirrors typing: read delay -> typing burst -> occasional pause -> send
* every sent line is stored in chat_memory, and near-duplicates are rejected

LLM_MOCK=1 forces the offline engine (tests, planes, no-key runs).
"""
from __future__ import annotations

import difflib
import random
import re
import time

import requests

from . import config, db
from .log import get_logger

log = get_logger("humanize")

DEFAULT_PERSONA = {
    "tone": "casual",
    "language": "id-mix",
    "emoji": 0.15,
    "typo": 0.03,
    "max_chars": 180,
    "wpm": (38, 62),
    "interests": ["crypto", "testnet", "nft", "airdrop"],
    "avoid": ["!loud", "ALL CAPS"],
}

ID_FILLERS = ["menurut gue", "jujur", "imo", "gak tau sih", "btw", "eh", "hmm", "serius?"]
ID_OPENERS = ["wah", "nah", "oke", "hmm", "btw", "eh"]
ID_CLOSERS = ["lah", "sih", "ya", "deh", "kah"]
EN_FILLERS = ["tbh", "imo", "ngl", "kinda", "honestly"]
EMOJI_POOL = ["👀", "🔥", "😅", "🙂", "💀", "🫡", "✨", "🤔", "😭", "👍"]
GREET = ["halo", "hai", "hey", "pagi", "malam", "morning", "gm"]


def persona(name_or_id: str | None) -> dict:
    p = dict(DEFAULT_PERSONA)
    if not name_or_id:
        return p
    all_p = config.personas().get("personas", {})
    found = all_p.get(name_or_id)
    if not found:
        for v in all_p.values():
            if v.get("label") == name_or_id:
                found = v
                break
    if found:
        p.update({k: v for k, v in found.items() if k != "label"})
    return p


def _rng_ok(prob: float) -> bool:
    return random.random() < prob


def _similar(a: str, b: str) -> float:
    return difflib.SequenceMatcher(None, a.lower(), b.lower()).ratio()


def recent(identity_id: str, channel: str, limit: int = 12) -> list[str]:
    rows = db.rows("SELECT text FROM chat_memory WHERE identity_id=? AND channel=? ORDER BY id DESC LIMIT ?",
                   (identity_id, channel, limit))
    return [r["text"] for r in rows][::-1]


def remember(identity_id: str, channel: str, author: str, text: str) -> None:
    db.execute("INSERT INTO chat_memory(identity_id,channel,author,text,ts) VALUES(?,?,?,?,?)",
               (identity_id, channel, author, text[:1000], db.now()))
    # keep memory bounded
    db.execute("DELETE FROM chat_memory WHERE id NOT IN (SELECT id FROM chat_memory ORDER BY id DESC LIMIT 5000)")


def is_duplicate(identity_id: str, channel: str, text: str, threshold: float = 0.82) -> bool:
    return any(_similar(text, old) > threshold for old in recent(identity_id, channel, 8))


# ---------------- LLM ----------------
PROVIDERS = [
    ("ANTHROPIC_API_KEY", "https://api.anthropic.com/v1/messages", "claude-3-5-haiku-latest"),
    ("KIMI_API_KEY", "https://api.moonshot.ai/v1/chat/completions", "moonshot-v1-8k"),
    ("OPENROUTER_API_KEY", "https://openrouter.ai/api/v1/chat/completions", "google/gemini-2.0-flash-001"),
    ("DEEPSEEK_API_KEY", "https://api.deepseek.com/chat/completions", "deepseek-chat"),
    ("GROQ_API_KEY", "https://api.groq.com/openai/v1/chat/completions", "llama-3.3-70b-versatile"),
]


def llm_available() -> bool:
    if (config.env("LLM_MOCK") or "0") == "1":
        return False
    return any(c.get("key") for c in _llm_configs())


def _persona_arg(p) -> dict:
    return persona(p) if isinstance(p, str) else (p or persona(None))


def _llm_configs() -> list[dict]:
    cfgs = []
    if config.env("GRIND_LLM_BASE_URL") and config.env("GRIND_LLM_API_KEY"):
        cfgs.append({"key": config.env("GRIND_LLM_API_KEY"), "url": config.env("GRIND_LLM_BASE_URL").rstrip("/") + "/chat/completions",
                     "model": config.env("GRIND_LLM_MODEL", "gpt-4o-mini"), "kind": "openai"})
    if config.env("RADAR_LLM_BASE_URL") and config.env("RADAR_LLM_API_KEY"):
        cfgs.append({"key": config.env("RADAR_LLM_API_KEY"), "url": config.env("RADAR_LLM_BASE_URL").rstrip("/") + "/chat/completions",
                     "model": config.env("RADAR_LLM_MODEL", "gpt-4o-mini"), "kind": "openai"})
    for env_key, url, model in PROVIDERS:
        k = config.env(env_key)
        if k:
            cfgs.append({"key": k, "url": url, "model": model,
                         "kind": "anthropic" if "anthropic" in url else "openai"})
    return cfgs


def llm(prompt: str, system: str = "", max_tokens: int = 220, temperature: float = 0.9) -> str | None:
    if config.env_bool("LLM_MOCK"):
        return None
    for c in _llm_configs():
        try:
            if c["kind"] == "anthropic":
                r = requests.post(c["url"], timeout=45, headers={"x-api-key": c["key"], "anthropic-version": "2023-06-01"},
                                  json={"model": c["model"], "max_tokens": max_tokens, "temperature": temperature,
                                        "system": system, "messages": [{"role": "user", "content": prompt}]})
                r.raise_for_status()
                return r.json()["content"][0]["text"].strip()
            r = requests.post(c["url"], timeout=45, headers={"Authorization": f"Bearer {c['key']}"},
                              json={"model": c["model"], "max_tokens": max_tokens, "temperature": temperature,
                                    "messages": ([{"role": "system", "content": system}] if system else [])
                                    + [{"role": "user", "content": prompt}]})
            r.raise_for_status()
            return r.json()["choices"][0]["message"]["content"].strip()
        except (requests.RequestException, KeyError, IndexError, ValueError) as e:
            log.warning("llm provider %s failed: %s", c["url"], e)
            continue
    return None


# ---------------- offline generation ----------------
def _offline(kind: str, p: dict, context: list[str], topic: str = "") -> str:
    lang = p.get("language", "id-mix")
    pool = ID_FILLERS + (EN_FILLERS if lang != "id" else [])
    if kind == "greeting":
        base = random.choice(GREET)
    elif kind == "reply" and context:
        prev = context[-1][:120]
        base = f"{random.choice(pool)} {prev.lower()[:90].rstrip('?!.')} itu worth dicoba"
        if lang == "en":
            base = f"{random.choice(pool)} that sounds worth a try"
    elif kind == "question":
        base = random.choice(["ada yang udah coba belum?", "ini masih open ya?", "menurut kalian gimana?",
                              "anyone tried this yet?", "is this still live?"])
    elif topic:
        base = f"{random.choice(pool)} {topic} " + random.choice(["lagi rame ya", "menarik sih", "masih early"])
    else:
        base = random.choice(["nice info", "mantap", "oke juga", "wkwk bener", "good point"])
    if _rng_ok(p.get("emoji", 0.1)) and lang != "en":
        base += " " + random.choice(EMOJI_POOL)
    return base


def topic_hint(p: dict) -> str:
    return random.choice(p.get("interests") or ["crypto"])


# ---------------- public API ----------------
def craft(identity_id: str, channel: str, persona_name: str | None = None, kind: str = "reply",
          topic: str = "", context: list[str] | None = None, instruction: str = "") -> str:
    p = persona(persona_name)
    ctx = context if context is not None else recent(identity_id, channel, 8)
    text = ""

    system = (f"You are a real human in a crypto community chat. Persona: {p.get('tone')} tone, "
              f"language {p.get('language')}, interests {', '.join(p.get('interests') or [])}. "
              f"Reply in ONE short message, max {p.get('max_chars', 180)} chars, lowercase-ish, no hashtags, "
              f"no 'as an AI', no links unless asked. Vary sentence shape.")
    prompt = ("Recent chat:\n" + "\n".join(f"- {c}" for c in ctx[-8:]) +
              f"\n\nYour task: {instruction or kind}. Topic hint: {topic or topic_hint(p)}.\n"
              "Write only the message text.")
    text = (llm(prompt, system, max_tokens=int(p.get("max_chars", 180)) // 2 + 40) or "").strip().strip('"')

    if not text or len(text) < 3:
        text = _offline(kind, p, ctx, topic)
    text = text.replace("\n", " ").strip()
    if len(text) > int(p.get("max_chars", 180)) * 1.5:
        text = text[: int(p.get("max_chars", 180))].rsplit(" ", 1)[0]

    # avoid repeats
    for _ in range(3):
        if not is_duplicate(identity_id, channel, text):
            break
        text = _offline(kind, p, ctx, topic)

    # persona typo pass (chat only, never URLs)
    if _rng_ok(float(p.get("typo", 0.03))):
        text = typo(text)
    remember(identity_id, channel, "agent", text)
    return text


def typo(text: str) -> str:
    words = text.split(" ")
    idx = [i for i, w in enumerate(words) if len(w) > 4 and "http" not in w and "/" not in w]
    if not idx:
        return text
    i = random.choice(idx)
    w = words[i]
    op = random.choice(["swap", "drop", "double"])
    if op == "swap" and len(w) > 5:
        j = random.randint(1, len(w) - 2)
        w = w[:j] + w[j + 1] + w[j] + w[j + 2:]
    elif op == "drop" and len(w) > 5:
        j = random.randint(1, len(w) - 2)
        w = w[:j] + w[j + 1:]
    else:
        j = random.randint(1, len(w) - 2)
        w = w[:j] + w[j] + w[j:]
    words[i] = w
    return " ".join(words)


def typing_seconds(text: str, p) -> float:
    p = _persona_arg(p)
    lo, hi = p.get("wpm") or (38, 62)
    cps = random.uniform(lo, hi) * 5 / 60  # chars per second
    return max(1.2, len(text) / max(cps, 1.2) * random.uniform(0.85, 1.25))


def plan_burst(text: str, p) -> list[str]:
    """Split a longer thought into 1-3 chat-sized chunks the way people actually type."""
    p = _persona_arg(p)
    if len(text) < 90 or _rng_ok(0.45):
        return [text]
    parts = re.split(r"(?<=[,.!?])\s+", text)
    out, cur = [], ""
    for part in parts:
        if len(cur) + len(part) > 110 and cur:
            out.append(cur.strip())
            cur = part
        else:
            cur = f"{cur} {part}".strip()
    if cur:
        out.append(cur.strip())
    return out[:3]


def read_delay() -> float:
    return random.uniform(2.5, 14.0)


def sleep_between_messages() -> None:
    time.sleep(random.uniform(0.8, 3.2))


def should_chime(chance: float = 0.55) -> bool:
    return random.random() < chance


def pick_persona_for(identity_id: str, fallback: str = "casual-id") -> str:
    row = db.one("SELECT persona FROM identities WHERE id=?", (identity_id,))
    return (row or {}).get("persona") or fallback
